    [96369] = "Report back to Commander Folkar.",
    [96376] = "<It occurs to you that as an advisor to the Warchief, Nazgrel might be very interested to see the documents you've recovered from Westfall. Ask him if any of these documents make any sense to him.>",
    [96377] = "<It occurs to you that Shaw's right-hand goblin might be interested to see the documents you've recovered from Westfall. Ask him if any of these documents make any sense to him.>",
    [96379] = "<It occurs to you that a goblin who deals in asset recovery might be very interested to see the documents you've recovered from Westfall. Ask him if any of these documents make any sense to him... and more importantly, what he might be willing to pay you for them.>",
    [96381] = "Enter the Alcaz Prison and slay 15  Strashasz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sully McCleary.",
