    [96783] = "Steal a Syndicate uniform from Northfold Manor to infiltrate Stromgarde Keep.",
    [96784] = "While disguised as a member of the Syndicate, find someone inside Stromgarde Keep who knows about the secret deal.",
    [96785] = "Find something within Stromgarde Keep to convince Anastasia to give up details of the secret deal.",
